    assert.equal(totals.total, 900);
  });

  it('handles multiple lines with voucher', () => {
    const invoice = {
      lines: [
        { qty: 2, unitPrice: 500, discountPercent: 10, vatRate: 21 },
        { qty: 3, unitPrice: 200, discountPercent: 5, vatRate: 9 },
      ],
      voucher: { code: 'SAVE20', amount: 50 },
    };
    const totals = invoiceTotals(invoice);
    const line1VAT = lineVAT({ qty: 2, unitPrice: 500, discountPercent: 10, vatRate: 21 });
    const line2VAT = lineVAT({ qty: 3, unitPrice: 200, discountPercent: 5, vatRate: 9 });
    const expected = 1600 - 130 + (line1VAT + line2VAT) - 50;
    assert.equal(totals.total, expected);
  });

  it('returns 0 for discount and VAT fields when not applicable', () => {
    const invoice = {
      lines: [{ qty: 2, unitPrice: 500, vatRate: 0 }],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.discount, 0);
    assert.equal(totals.vat, 0);
  });

  it('does not mutate the input', () => {
    const invoice = {
      lines: [{ qty: 2, unitPrice: 500, vatRate: 21 }],
    };
    const invoiceCopy = JSON.parse(JSON.stringify(invoice));
    invoiceTotals(invoice);
    assert.deepEqual(invoice, invoiceCopy);
  });

  it('returns new object on each call', () => {
    const invoice = {
      lines: [{ qty: 2, unitPrice: 500, vatRate: 21 }],
    };
    const totals1 = invoiceTotals(invoice);
    const totals2 = invoiceTotals(invoice);
    assert.notEqual(totals1, totals2);
    assert.deepEqual(totals1, totals2);
  });

  it('handles large invoices', () => {
    const invoice = {
      lines: Array.from({ length: 100 }, (_, i) => ({
        qty: i + 1,
        unitPrice: 100,
        vatRate: 21,
      })),
    };
    const totals = invoiceTotals(invoice);
    assert.equal(Number.isInteger(totals.subtotal), true);
    assert.equal(Number.isInteger(totals.vat), true);
    const expected = Array.from({ length: 100 }, (_, i) => (i + 1) * 100).reduce((a, b) => a + b);
    assert.equal(totals.subtotal, expected);
  });

  it('returns all required fields', () => {
    const invoice = {
      lines: [{ qty: 2, unitPrice: 500, vatRate: 0 }],
    };
    const totals = invoiceTotals(invoice);
    assert.ok(totals.hasOwnProperty('subtotal'));
    assert.ok(totals.hasOwnProperty('discount'));
    assert.ok(totals.hasOwnProperty('vat'));
    assert.ok(totals.hasOwnProperty('voucher'));
    assert.ok(totals.hasOwnProperty('total'));
  });

  it('returns 0 for voucher when not present', () => {
    const invoice = {
      lines: [{ qty: 2, unitPrice: 500, vatRate: 0 }],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.voucher, 0);
  });

  it('includes bulk discount in discount field for qty >= 10', () => {
    const invoice = {
      lines: [{ qty: 10, unitPrice: 100, discountPercent: 0, vatRate: 0 }],
    };
    const totals = invoiceTotals(invoice);
    const expectedDiscount = 25;
    assert.equal(totals.discount, expectedDiscount);
  });

  it('applies bulk discount after line discount', () => {
    const invoice = {
      lines: [{ qty: 10, unitPrice: 100, discountPercent: 10, vatRate: 0 }],
    };
    const totals = invoiceTotals(invoice);
    const lineDisc = 100;
    const bulkDisc = 23;
    const expectedDiscount = lineDisc + bulkDisc;
    assert.equal(totals.discount, expectedDiscount);
  });

  it('no bulk discount for qty < 10', () => {
    const invoice = {
      lines: [{ qty: 9, unitPrice: 100, discountPercent: 0, vatRate: 0 }],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.discount, 0);
  });

  it('bulk discount applied per line in multi-line invoice', () => {
    const invoice = {
      lines: [
        { qty: 5, unitPrice: 100, discountPercent: 0, vatRate: 0 },
        { qty: 10, unitPrice: 100, discountPercent: 0, vatRate: 0 },
        { qty: 15, unitPrice: 100, discountPercent: 0, vatRate: 0 },
      ],
    };
    const totals = invoiceTotals(invoice);
    const line1Bulk = 0;
    const line2Bulk = 25;
    const line3Bulk = 38;
    const expectedDiscount = line1Bulk + line2Bulk + line3Bulk;
    assert.equal(totals.discount, expectedDiscount);
  });

  it('calculates correct total with bulk discount', () => {
    const invoice = {
      lines: [{ qty: 10, unitPrice: 100, discountPercent: 0, vatRate: 21 }],
    };
    const totals = invoiceTotals(invoice);
    const subtotal = 1000;
    const lineDisc = 0;
    const bulkDisc = 25;
    const totalDisc = lineDisc + bulkDisc;
    const amountAfterDisc = subtotal - totalDisc;
    const vat = Math.round(amountAfterDisc * 0.21);
    const expectedTotal = subtotal - totalDisc + vat;
    assert.equal(totals.total, expectedTotal);
  });

  it('handles bulk discount with voucher', () => {
    const invoice = {
      lines: [{ qty: 10, unitPrice: 100, discountPercent: 0, vatRate: 0 }],
      voucher: { code: 'SAVE5', amount: 50 },
    };
    const totals = invoiceTotals(invoice);
    const subtotal = 1000;
    const bulkDisc = 25;
    const expectedTotal = subtotal - bulkDisc - 50;
    assert.equal(totals.total, expectedTotal);
  });
});

