    it('applies silver tier discount (2.5%) when discountPercent not provided', () => {
      const products = listProducts();
      const customers = listCustomers();
      const silverCustomer = customers.find((c) => c.tier === 'silver');

      const result = createInvoice({
        customerId: silverCustomer.id,
        issueDate: '2025-01-15',
        lines: [{ sku: products[0].sku, qty: 1 }],
      });

      assert.equal(result.ok, true);
      assert.equal(result.value.lines[0].discountPercent, 2.5);
    });

    it('applies standard tier discount (0%) when discountPercent not provided', () => {
      const products = listProducts();
      const customers = listCustomers();
      const standardCustomer = customers.find((c) => c.tier === 'standard');

      const result = createInvoice({
        customerId: standardCustomer.id,
        issueDate: '2025-01-15',
        lines: [{ sku: products[0].sku, qty: 1 }],
      });

      assert.equal(result.ok, true);
      assert.equal(result.value.lines[0].discountPercent, 0);
