  describe('SKU validation', () => {
    it('returns UNKNOWN_SKU for unknown product', () => {
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: '2025-01-15',
        lines: [{ sku: 'UNKNOWN-SKU-12345', qty: 1 }],
      });

      assert.equal(result.ok, false);
      assert.equal(result.error, 'UNKNOWN_SKU');
    });

    it('returns UNKNOWN_SKU when first line has unknown SKU', () => {
      const products = listProducts();
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: '2025-01-15',
        lines: [
          { sku: 'UNKNOWN-SKU', qty: 1 },
          { sku: products[0].sku, qty: 1 },
        ],
      });

      assert.equal(result.ok, false);
      assert.equal(result.error, 'UNKNOWN_SKU');
    });

    it('returns UNKNOWN_SKU when second line has unknown SKU', () => {
      const products = listProducts();
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: '2025-01-15',
        lines: [
          { sku: products[0].sku, qty: 1 },
          { sku: 'UNKNOWN-SKU', qty: 1 },
        ],
      });

      assert.equal(result.ok, false);
      assert.equal(result.error, 'UNKNOWN_SKU');
    });
  });

  describe('error priority', () => {
    it('validates customer before date', () => {
      const products = listProducts();
      const result = createInvoice({
        customerId: 'unknown',
        issueDate: 'invalid-date',
        lines: [{ sku: products[0].sku, qty: 1 }],
      });

      assert.equal(result.error, 'CUSTOMER_NOT_FOUND');
    });

    it('validates date before lines', () => {
      const products = listProducts();
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: 'invalid-date',
        lines: [],
      });

      assert.equal(result.error, 'DATE_INVALID');
    });

    it('validates lines array before line contents', () => {
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: '2025-01-15',
        lines: [],
      });

      assert.equal(result.error, 'NO_LINES');
    });
  });

  describe('terms and dueDate', () => {
    it('sets default terms to NET30', () => {
      const products = listProducts();
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: '2025-01-15',
        lines: [{ sku: products[0].sku, qty: 1 }],
      });

      assert.equal(result.ok, true);
      assert.equal(result.value.terms, 'NET30');
    });

    it('calculates dueDate for NET30 (30 days after issue)', () => {
      const products = listProducts();
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: '2025-01-15',
        lines: [{ sku: products[0].sku, qty: 1 }],
        terms: 'NET30',
      });

      assert.equal(result.ok, true);
      assert.equal(result.value.terms, 'NET30');
      assert.equal(result.value.dueDate, '2025-02-14');
    });

    it('calculates dueDate for NET14 (14 days after issue)', () => {
      const products = listProducts();
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: '2025-01-15',
        lines: [{ sku: products[0].sku, qty: 1 }],
        terms: 'NET14',
      });

      assert.equal(result.ok, true);
      assert.equal(result.value.terms, 'NET14');
      assert.equal(result.value.dueDate, '2025-01-29');
    });

    it('calculates dueDate for EOM (end of month)', () => {
      const products = listProducts();
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: '2025-01-15',
        lines: [{ sku: products[0].sku, qty: 1 }],
        terms: 'EOM',
      });

      assert.equal(result.ok, true);
      assert.equal(result.value.terms, 'EOM');
      assert.equal(result.value.dueDate, '2025-01-31');
    });

    it('calculates EOM correctly for last day of month', () => {
      const products = listProducts();
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: '2025-01-31',
        lines: [{ sku: products[0].sku, qty: 1 }],
        terms: 'EOM',
      });

      assert.equal(result.value.dueDate, '2025-01-31');
    });

    it('calculates EOM correctly across month boundary', () => {
      const products = listProducts();
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: '2025-01-30',
        lines: [{ sku: products[0].sku, qty: 1 }],
        terms: 'EOM',
      });

      assert.equal(result.value.dueDate, '2025-01-31');
    });

    it('calculates EOM correctly for February', () => {
      const products = listProducts();
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: '2025-02-10',
        lines: [{ sku: products[0].sku, qty: 1 }],
        terms: 'EOM',
      });

      assert.equal(result.value.dueDate, '2025-02-28');
    });

    it('calculates EOM correctly for leap year February', () => {
      const products = listProducts();
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: '2024-02-10',
        lines: [{ sku: products[0].sku, qty: 1 }],
        terms: 'EOM',
      });

      assert.equal(result.value.dueDate, '2024-02-29');
    });

    it('calculates EOM correctly at year boundary', () => {
      const products = listProducts();
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: '2025-12-15',
        lines: [{ sku: products[0].sku, qty: 1 }],
        terms: 'EOM',
      });

      assert.equal(result.value.dueDate, '2025-12-31');
    });

    it('rejects unknown terms', () => {
      const products = listProducts();
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: '2025-01-15',
        lines: [{ sku: products[0].sku, qty: 1 }],
        terms: 'NET45',
      });

      assert.equal(result.ok, false);
      assert.equal(result.error, 'TERMS_INVALID');
    });

    it('rejects empty string terms', () => {
      const products = listProducts();
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: '2025-01-15',
        lines: [{ sku: products[0].sku, qty: 1 }],
        terms: '',
      });

      assert.equal(result.ok, false);
      assert.equal(result.error, 'TERMS_INVALID');
    });

    it('validates terms before processing lines', () => {
      const products = listProducts();
      const customers = listCustomers();
      const result = createInvoice({
        customerId: customers[0].id,
        issueDate: '2025-01-15',
        lines: [],
        terms: 'INVALID',
      });

      assert.equal(result.ok, false);
      assert.equal(result.error, 'TERMS_INVALID');
    });
  });
});

describe('lineTotal', () => {
  it('calculates qty times unitPrice', () => {
    const total = lineTotal({ qty: 3, unitPrice: 500 });
    assert.equal(total, 1500);
  });

  it('returns a whole number of cents', () => {
    const total = lineTotal({ qty: 3, unitPrice: 500 });
    assert.equal(Number.isInteger(total), true);
  });

  it('handles qty of 1', () => {
    const total = lineTotal({ qty: 1, unitPrice: 999 });
